-- Review workflow templates used by Provider Portal through the shared notification capability.
insert into notifications_ext.templates(template_key,title_translations,body_translations,channels,variables,is_active,metadata) values
('lsevin.review.created',
 '{"fa-IR":"نظر جدید مشتری","en-US":"New customer review","ar-SA":"تقييم جديد من العميل","tr-TR":"Yeni müşteri yorumu","es-ES":"Nueva reseña de cliente","ku-KU":"هەڵسەنگاندنی نوێی کڕیار","de-DE":"Neue Kundenbewertung","fr-FR":"Nouvel avis client"}'::jsonb,
 '{"fa-IR":"یک نظر جدید برای مجموعه شما در ال سوین ثبت شد.","en-US":"A new review was created for your workspace on LSevin.","ar-SA":"تمت إضافة تقييم جديد لمساحة عملك على LSevin.","tr-TR":"LSevin çalışma alanınız için yeni bir yorum oluşturuldu.","es-ES":"Se creó una nueva reseña para tu espacio en LSevin.","ku-KU":"هەڵسەنگاندنێکی نوێ بۆ شوێنی کارەکەت لە LSevin تۆمار کرا.","de-DE":"Für Ihren Arbeitsbereich auf LSevin wurde eine neue Bewertung erstellt.","fr-FR":"Un nouvel avis a été créé pour votre espace LSevin."}'::jsonb,
 array['in_app','push'], array['reviewId','providerId','staffId'], true, '{"journey":"reviews","audience":"reviews"}'::jsonb),
('review.reply.pending',
 '{"fa-IR":"پاسخ نظر در انتظار تایید","en-US":"Review response awaiting approval","ar-SA":"رد التقييم بانتظار الموافقة","tr-TR":"Yorum yanıtı onay bekliyor","es-ES":"La respuesta espera aprobación","ku-KU":"وەڵامی هەڵسەنگاندن چاوەڕێی پەسەندکردنە","de-DE":"Bewertungsantwort wartet auf Freigabe","fr-FR":"Réponse en attente de validation"}'::jsonb,
 '{"fa-IR":"پاسخ شما ثبت شد و پس از بررسی منتشر می‌شود.","en-US":"Your response was saved and will publish after moderation.","ar-SA":"تم حفظ ردك وسيتم نشره بعد المراجعة.","tr-TR":"Yanıtınız kaydedildi ve moderasyondan sonra yayınlanacak.","es-ES":"Tu respuesta se guardó y se publicará tras la moderación.","ku-KU":"وەڵامەکەت پاشەکەوت کرا و دوای پشکنین بڵاودەکرێتەوە.","de-DE":"Ihre Antwort wurde gespeichert und nach der Moderation veröffentlicht.","fr-FR":"Votre réponse est enregistrée et sera publiée après modération."}'::jsonb,
 array['in_app'], array['reviewId','providerId','staffId'], true, '{"journey":"reviews","audience":"reviews"}'::jsonb),
('review.reply.approved',
 '{"fa-IR":"پاسخ نظر منتشر شد","en-US":"Review response published","ar-SA":"تم نشر رد التقييم","tr-TR":"Yorum yanıtı yayınlandı","es-ES":"Respuesta publicada","ku-KU":"وەڵامی هەڵسەنگاندن بڵاوکرایەوە","de-DE":"Bewertungsantwort veröffentlicht","fr-FR":"Réponse publiée"}'::jsonb,
 '{"fa-IR":"پاسخ رسمی شما تایید و در ال سوین منتشر شد.","en-US":"Your official review response was approved and published on LSevin.","ar-SA":"تمت الموافقة على ردك الرسمي ونشره على LSevin.","tr-TR":"Resmi yorum yanıtınız onaylandı ve LSevin üzerinde yayınlandı.","es-ES":"Tu respuesta oficial fue aprobada y publicada en LSevin.","ku-KU":"وەڵامی فەرمییەکەت پەسەند کرا و لە LSevin بڵاوکرایەوە.","de-DE":"Ihre offizielle Antwort wurde freigegeben und auf LSevin veröffentlicht.","fr-FR":"Votre réponse officielle a été approuvée et publiée sur LSevin."}'::jsonb,
 array['in_app','push','email'], array['reviewId','providerId','staffId'], true, '{"journey":"reviews","audience":"reviews"}'::jsonb),
('review.reply.rejected',
 '{"fa-IR":"پاسخ نظر تایید نشد","en-US":"Review response not approved","ar-SA":"لم تتم الموافقة على رد التقييم","tr-TR":"Yorum yanıtı onaylanmadı","es-ES":"Respuesta no aprobada","ku-KU":"وەڵامی هەڵسەنگاندن پەسەند نەکرا","de-DE":"Bewertungsantwort nicht freigegeben","fr-FR":"Réponse non approuvée"}'::jsonb,
 '{"fa-IR":"پاسخ رسمی شما در بررسی تایید نشد. می‌توانید متن را بازبینی کنید.","en-US":"Your official review response was not approved. You can revise the response before trying again.","ar-SA":"لم تتم الموافقة على ردك الرسمي. يمكنك مراجعته قبل المحاولة مرة أخرى.","tr-TR":"Resmi yorum yanıtınız onaylanmadı. Yeniden denemeden önce düzenleyebilirsiniz.","es-ES":"Tu respuesta oficial no fue aprobada. Puedes revisarla antes de volver a intentarlo.","ku-KU":"وەڵامی فەرمییەکەت پەسەند نەکرا. پێش هەوڵدانەوە دەتوانیت دەستکاری بکەیت.","de-DE":"Ihre offizielle Antwort wurde nicht freigegeben. Sie können sie vor einem neuen Versuch überarbeiten.","fr-FR":"Votre réponse officielle n’a pas été approuvée. Vous pouvez la réviser avant de réessayer."}'::jsonb,
 array['in_app','email'], array['reviewId','providerId','staffId'], true, '{"journey":"reviews","audience":"reviews"}'::jsonb),
('review.report.received',
 '{"fa-IR":"گزارش نظر دریافت شد","en-US":"Review report received","ar-SA":"تم استلام بلاغ التقييم","tr-TR":"Yorum bildirimi alındı","es-ES":"Reporte de reseña recibido","ku-KU":"ڕاپۆرتی هەڵسەنگاندن وەرگیرا","de-DE":"Bewertungsmeldung eingegangen","fr-FR":"Signalement reçu"}'::jsonb,
 '{"fa-IR":"گزارش شما برای بررسی تیم ال سوین ثبت شد.","en-US":"Your review report was submitted to the LSevin moderation team.","ar-SA":"تم إرسال بلاغك إلى فريق مراجعة LSevin.","tr-TR":"Yorum bildiriminiz LSevin moderasyon ekibine gönderildi.","es-ES":"Tu reporte fue enviado al equipo de moderación de LSevin.","ku-KU":"ڕاپۆرتەکەت بۆ تیمی پشکنینی LSevin نێردرا.","de-DE":"Ihre Meldung wurde an das LSevin-Moderationsteam gesendet.","fr-FR":"Votre signalement a été transmis à l’équipe de modération LSevin."}'::jsonb,
 array['in_app'], array['reviewId','reportId','providerId','staffId'], true, '{"journey":"reviews","audience":"reviews"}'::jsonb),
('review.report.actioned',
 '{"fa-IR":"گزارش نظر پیگیری شد","en-US":"Review report actioned","ar-SA":"تم اتخاذ إجراء بشأن البلاغ","tr-TR":"Yorum bildirimi işlendi","es-ES":"Se actuó sobre el reporte","ku-KU":"ڕاپۆرتی هەڵسەنگاندن چارەسەر کرا","de-DE":"Bewertungsmeldung bearbeitet","fr-FR":"Signalement traité"}'::jsonb,
 '{"fa-IR":"تیم ال سوین گزارش شما را بررسی و اقدام لازم را ثبت کرد.","en-US":"The LSevin team reviewed your report and recorded an action.","ar-SA":"راجع فريق LSevin بلاغك وسجل الإجراء المناسب.","tr-TR":"LSevin ekibi bildiriminizi inceledi ve gerekli işlemi kaydetti.","es-ES":"El equipo de LSevin revisó tu reporte y registró una acción.","ku-KU":"تیمی LSevin ڕاپۆرتەکەت پشکنی و کردارێکی پێویستی تۆمار کرد.","de-DE":"Das LSevin-Team hat Ihre Meldung geprüft und eine Maßnahme erfasst.","fr-FR":"L’équipe LSevin a examiné votre signalement et enregistré une action."}'::jsonb,
 array['in_app','email'], array['reviewId','reportId','providerId','staffId'], true, '{"journey":"reviews","audience":"reviews"}'::jsonb),
('review.report.dismissed',
 '{"fa-IR":"بررسی گزارش نظر تکمیل شد","en-US":"Review report review completed","ar-SA":"اكتملت مراجعة بلاغ التقييم","tr-TR":"Yorum bildirimi incelemesi tamamlandı","es-ES":"Revisión del reporte completada","ku-KU":"پشکنینی ڕاپۆرتی هەڵسەنگاندن تەواو بوو","de-DE":"Prüfung der Bewertungsmeldung abgeschlossen","fr-FR":"Examen du signalement terminé"}'::jsonb,
 '{"fa-IR":"تیم ال سوین گزارش شما را بررسی کرد و موردی برای اقدام بیشتر ثبت نشد.","en-US":"The LSevin team reviewed your report and no further action was recorded.","ar-SA":"راجع فريق LSevin بلاغك ولم يتم تسجيل إجراء إضافي.","tr-TR":"LSevin ekibi bildiriminizi inceledi ve ek işlem kaydedilmedi.","es-ES":"El equipo de LSevin revisó tu reporte y no registró acciones adicionales.","ku-KU":"تیمی LSevin ڕاپۆرتەکەت پشکنی و هیچ کرداری زیاتر تۆمار نەکرا.","de-DE":"Das LSevin-Team hat Ihre Meldung geprüft; es wurde keine weitere Maßnahme erfasst.","fr-FR":"L’équipe LSevin a examiné votre signalement et aucune action supplémentaire n’a été enregistrée."}'::jsonb,
 array['in_app'], array['reviewId','reportId','providerId','staffId'], true, '{"journey":"reviews","audience":"reviews"}'::jsonb)
on conflict (template_key) do update set
  title_translations=excluded.title_translations,
  body_translations=excluded.body_translations,
  channels=excluded.channels,
  variables=excluded.variables,
  is_active=excluded.is_active,
  metadata=excluded.metadata,
  updated_at=now();
